ACTIONS = ("add", "change", "delete", "view")


def copy_page_permissions_to_searchpage(apps, schema_editor):
    """Create the proxy permissions and mirror ``*_page`` grants to ``*_searchpage`` only.

    ``*_websitepage`` is never granted here: website editing rights are assigned
    explicitly by an administrator.
    """
    app_config = apps.get_app_config("pages")
    app_config.models_module = True  # create_permissions skips configs without models_module
    try:
        create_permissions(app_config, apps=apps, verbosity=0)
    finally:
        app_config.models_module = None

    Permission = apps.get_model("auth", "Permission")
    Group = apps.get_model("auth", "Group")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    for action in ACTIONS:
        source = Permission.objects.filter(
            content_type__app_label="pages", codename=f"{action}_page"
        ).first()
        target = Permission.objects.filter(
            content_type__app_label="pages", codename=f"{action}_searchpage"
        ).first()
        if source is None or target is None:
            continue
        for group in Group.objects.filter(permissions=source):
            group.permissions.add(target)
        for user in User.objects.filter(user_permissions=source):
            user.user_permissions.add(target)


